// marshalTypesSigintSignalToSigintSignalResponseBody builds a value of type
// *SigintSignalResponseBody from a value of type *types.SigintSignal.
func marshalTypesSigintSignalToSigintSignalResponseBody(v *types.SigintSignal) *SigintSignalResponseBody {
	res := &SigintSignalResponseBody{
		ID:                 v.ID,
		ProjectID:          v.ProjectID,
		Name:               v.Name,
		Description:        v.Description,
		ClassifierCriteria: v.ClassifierCriteria,
		CreatedAt:          v.CreatedAt,
		UpdatedAt:          v.UpdatedAt,
	}

	return res
}

// marshalTypesSigintSensorToSigintSensorResponseBody builds a value of type
// *SigintSensorResponseBody from a value of type *types.SigintSensor.
func marshalTypesSigintSensorToSigintSensorResponseBody(v *types.SigintSensor) *SigintSensorResponseBody {
	res := &SigintSensorResponseBody{
		ID:           v.ID,
		ProjectID:    v.ProjectID,
		Name:         v.Name,
		Description:  v.Description,
		Instructions: v.Instructions,
		Mode:         string(v.Mode),
		CreatedAt:    v.CreatedAt,
		UpdatedAt:    v.UpdatedAt,
	}
	if v.SignalIds != nil {
		res.SignalIds = make([]string, len(v.SignalIds))
		for i, val := range v.SignalIds {
			res.SignalIds[i] = val
		}
	} else {
		res.SignalIds = []string{}
	}

	return res
}
